Scripts.OnHide:
if (self.withMask) then
	Atr_Mask:Hide();
	self.withMask = nil;
end

Scripts.OnChar:
if ( not self:IsInIMECompositionMode() ) then
	Atr_Item_Autocomplete(self);
end

Scripts.OnLoad:
self:RegisterForDrag("LeftButton");
if (Atr_PM_VendorDesc) then Atr_PM_VendorDesc:SetText("Sale price over vendoring, per item. Items below the threshold move to \"Not Profitable\"."); end
if (Atr_PM_CraftDesc) then Atr_PM_CraftDesc:SetText("For crafted items: auction price minus reagent cost. Items whose crafting margin is below the threshold move to \"Not Profitable\" (hold onto them)."); end
